"""Figures for the README (all generated by scripts/run_experiments.py)."""
from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

from .config import CLASSES, FS_HZ
from .features import FEATURE_NAMES, highpass
from .signals import make_window

PALETTE = {"background": "#8a95a5", "motor_start": "#3b7dd8", "lightning": "#e07a1f",
           "switching": "#7a4fb5", "energizer": "#c8433a"}
NAVY = "#1f3a5f"

plt.rcParams.update({"figure.dpi": 130, "savefig.dpi": 160, "savefig.bbox": "tight", "font.size": 10,
                     "axes.titlesize": 11, "axes.titleweight": "bold", "axes.spines.top": False,
                     "axes.spines.right": False, "axes.grid": True, "grid.alpha": 0.25, "axes.axisbelow": True})


def _save(fig, out, name):
    p = Path(out) / name
    fig.savefig(p)
    plt.close(fig)
    return p


def signal_gallery(out, seed=7):
    rng = np.random.default_rng(seed)
    fig, axes = plt.subplots(2, 5, figsize=(15, 5), sharex="col")
    for j, kind in enumerate(CLASSES):
        x = make_window(kind, rng, snr_db=40, amp_scale=1.0)
        t = np.arange(len(x)) / FS_HZ * 1e3
        hp = highpass(x, FS_HZ)
        axes[0, j].plot(t, x, color=PALETTE[kind], lw=1)
        axes[0, j].set_title(kind.replace("_", " "))
        axes[1, j].plot(t, hp, color=PALETTE[kind], lw=1)
        axes[1, j].set_xlabel("time (ms)")
    axes[0, 0].set_ylabel("raw sensor (pu)")
    axes[1, 0].set_ylabel("high-passed >1 kHz (pu)")
    fig.suptitle("Simulated sensor captures (10 ms window, 200 kS/s, 12-bit)", fontweight="bold")
    fig.tight_layout()
    return _save(fig, out, "01_signal_gallery.png")


def feature_space(X, y, out):
    fig, ax = plt.subplots(1, 2, figsize=(11, 4.2))
    for c, kind in enumerate(CLASSES):
        m = y == c
        ax[0].scatter(X.loc[m, "rise_time_us"], X.loc[m, "hp_peak_pu"], s=8, alpha=0.45, color=PALETTE[kind], label=kind)
        ax[1].scatter(X.loc[m, "width_us"], X.loc[m, "ring_count"] + np.random.default_rng(0).uniform(-.2, .2, m.sum()),
                      s=8, alpha=0.45, color=PALETTE[kind], label=kind)
    ax[0].set(xscale="log", yscale="log", xlim=(2, 3000), xlabel="rise time 10-90% (us)", ylabel="high-passed peak (pu)", title="Edge speed vs amplitude")
    ax[1].set(xscale="log", xlim=(2, 3000), xlabel="pulse width FWHM (us)", ylabel="ring count (jittered)", title="Pulse width vs ringing")
    ax[0].legend(markerscale=2, fontsize=8)
    return _save(fig, out, "02_feature_space.png")


def confusion(cm, out):
    cm = np.array(cm)
    norm = cm / cm.sum(axis=1, keepdims=True)
    fig, ax = plt.subplots(figsize=(6, 5.2))
    im = ax.imshow(norm, cmap="Blues", vmin=0, vmax=1)
    labels = [c.replace("_", "\n") for c in CLASSES]
    ax.set_xticks(range(5), labels)
    ax.set_yticks(range(5), labels)
    ax.grid(False)
    for i in range(5):
        for j in range(5):
            ax.text(j, i, f"{cm[i, j]}", ha="center", va="center", color="white" if norm[i, j] > .5 else "black")
    ax.set(xlabel="predicted", ylabel="true", title="Random Forest confusion matrix (test set)")
    fig.colorbar(im, ax=ax, label="row-normalised", shrink=0.8)
    return _save(fig, out, "03_confusion_matrix.png")


def importance(rf, out):
    imp = rf.feature_importances_
    o = np.argsort(imp)
    fig, ax = plt.subplots(figsize=(6.5, 4.5))
    ax.barh(np.array(FEATURE_NAMES)[o], imp[o], color=NAVY)
    ax.set(xlabel="impurity importance", title="Random Forest feature importance")
    return _save(fig, out, "04_feature_importance.png")


def snr_robustness(snr, f1, rec, out):
    fig, ax = plt.subplots(figsize=(6.5, 4))
    ax.plot(snr, f1, "o-", color=NAVY, label="macro F1 (5 classes)")
    ax.plot(snr, rec, "s--", color=PALETTE["energizer"], label="energizer recall")
    ax.axvspan(20, 45, color="#bcd3f0", alpha=0.3, label="training SNR range")
    ax.set(xlabel="SNR: 1 pu mains peak / noise std (dB)", ylabel="score", ylim=(0, 1.02), title="Noise robustness")
    ax.invert_xaxis()
    ax.legend(loc="lower left")
    return _save(fig, out, "05_snr_robustness.png")


def sampling_rate(fs, f1, rec, out):
    fig, ax = plt.subplots(figsize=(6.5, 4))
    ax.plot(np.array(fs) / 1e3, f1, "o-", color=NAVY, label="macro F1")
    ax.plot(np.array(fs) / 1e3, rec, "s--", color=PALETTE["energizer"], label="energizer recall")
    ax.set(xscale="log", xlabel="sampling rate (kS/s)", ylabel="score", ylim=(0.5, 1.0), title="Classification vs ADC sampling rate")
    ax.set_xticks(np.array(fs) / 1e3, [f"{v/1e3:g}" for v in fs])
    ax.legend()
    return _save(fig, out, "06_sampling_rate_classification.png")


def localization_heatmap(fs_list, sync_list, grid, out):
    fig, ax = plt.subplots(figsize=(7, 4.6))
    im = ax.imshow(grid, cmap="viridis_r", aspect="auto", origin="lower")
    ax.set_xticks(range(len(sync_list)), [f"{s*1e6:g}" for s in sync_list])
    ax.set_yticks(range(len(fs_list)), [f"{f/1e3:g}" for f in fs_list])
    ax.grid(False)
    for i in range(grid.shape[0]):
        for j in range(grid.shape[1]):
            ax.text(j, i, f"{grid[i, j]:.0f}", ha="center", va="center", color="white" if grid[i, j] < np.nanmax(grid) * .55 else "black", fontsize=9)
    ax.set(xlabel="clock-sync jitter between nodes (us, 1 sigma)", ylabel="sampling rate (kS/s)",
           title="Median localisation error (m), 3 sensors over 10 km")
    fig.colorbar(im, ax=ax, label="metres")
    return _save(fig, out, "07_localization_error_heatmap.png")


def localization_scatter(x_true, x_hat, out, label):
    err = np.array(x_hat) - np.array(x_true)
    fig, ax = plt.subplots(1, 2, figsize=(11, 4.2))
    ax[0].scatter(x_true, x_hat, s=10, color=NAVY, alpha=0.6)
    ax[0].plot([0, 10000], [0, 10000], "--", color=PALETTE["energizer"])
    ax[0].set(xlabel="true fence position (m)", ylabel="estimated (m)", title=f"TOA localisation ({label})")
    ax[1].hist(err, bins=30, color=NAVY, alpha=0.85)
    ax[1].set(xlabel="error (m)", ylabel="count", title=f"median |error| {np.median(np.abs(err)):.0f} m, p90 {np.percentile(np.abs(err), 90):.0f} m")
    return _save(fig, out, "08_localization_scatter.png")


def span_ambiguity(xs, med, p90, sensor_pos, out):
    fig, ax = plt.subplots(figsize=(7.5, 4))
    ax.plot(xs, med, "o-", color=NAVY, label="median |error|")
    ax.plot(xs, p90, "s--", color=PALETTE["lightning"], label="90th percentile")
    for p in sensor_pos:
        ax.axvline(p, color="#8a95a5", ls=":")
    ax.axvspan(max(sensor_pos), max(xs), color="#f3d6d3", alpha=0.5, label="beyond last sensor: unobservable")
    ax.set(xlabel="true fence position (m)", ylabel="localisation error (m)", title="Fences must lie between sensors")
    ax.legend()
    return _save(fig, out, "09_span_ambiguity.png")


def sensor_count(labels, med, p90, out):
    fig, ax = plt.subplots(figsize=(6, 4))
    x = np.arange(len(labels))
    ax.bar(x - 0.18, med, 0.36, color=NAVY, label="median")
    ax.bar(x + 0.18, p90, 0.36, color=PALETTE["lightning"], label="90th percentile")
    ax.set_xticks(x, labels)
    ax.set(ylabel="|error| (m)", title="Effect of sensor count (fs 200 kS/s, 1 us sync)")
    ax.legend()
    return _save(fig, out, "10_sensor_count.png")


def timeline(guardian, events, alert, out):
    fig, ax = plt.subplots(figsize=(11, 3.8))
    marker = {"lightning": ("v", PALETTE["lightning"]), "motor_start": ("s", PALETTE["motor_start"]),
              "switching": ("D", PALETTE["switching"]), "energizer": ("o", PALETTE["energizer"])}
    for e in events:
        m, c = marker[e["kind"]]
        ax.scatter(e["t"], 1, marker=m, color=c, s=45, label=e["kind"].replace("_", " "))
    cand = [h[0] for h in guardian.history if h[1] == 4 and h[0] is not None]
    ax.scatter(cand, [0.5] * len(cand), marker="|", s=250, color=NAVY, label="classified 'energizer'")
    if alert is not None:
        ax.axvline(alert.raised_at_s, color="green", lw=2, ls="--", label=f"ALERT ({alert.n_pulses} pulses)")
    h, l = ax.get_legend_handles_labels()
    uniq = dict(zip(l, h))
    ax.legend(uniq.values(), uniq.keys(), ncol=3, fontsize=8, loc="upper center", bbox_to_anchor=(0.5, -0.22))
    ax.set(xlabel="time (s)", yticks=[0.5, 1], yticklabels=["gateway\ndecision", "true event"], ylim=(0.2, 1.3),
           title="Example event stream: fence pulses amid lightning, motor starts and switching surges")
    return _save(fig, out, "11_alert_timeline.png")


def end_to_end(tta, loc_err, rates, out):
    fig, ax = plt.subplots(1, 3, figsize=(14, 4))
    ax[0].hist(tta, bins=15, color=NAVY)
    ax[0].set(xlabel="time from first fence pulse to alert (s)", ylabel="runs", title="Time to alert")
    ax[1].hist(loc_err, bins=20, color=NAVY)
    ax[1].set(xlabel="location error (m)", ylabel="runs", title=f"Location error (median |e| {np.median(np.abs(loc_err)):.0f} m)")
    names = list(rates)
    vals = [rates[n] for n in names]
    ax[2].bar(names, vals, color=[PALETTE["lightning"], PALETTE["energizer"]])
    ax[2].set(ylabel="per simulated hour", ylim=(0, max(vals) * 1.25 + 1e-9), title="Why pulse-train validation matters")
    for i, v in enumerate(vals):
        ax[2].text(i, v, f"{v:.2f}" if v else "0 (none observed)", ha="center", va="bottom")
    ax[2].tick_params(axis="x", labelsize=8)
    fig.tight_layout()
    return _save(fig, out, "12_end_to_end.png")


def snr_detection(snrs, det, med_err, out):
    fig, ax = plt.subplots(figsize=(6.5, 4))
    ax.plot(snrs, np.array(det) * 100, "o-", color=NAVY)
    ax.set(xlabel="SNR (dB)", ylabel="fences detected within 60 s (%)", ylim=(0, 105), title="End-to-end detection vs noise")
    ax2 = ax.twinx()
    ax2.plot(snrs, med_err, "s--", color=PALETTE["lightning"])
    ax2.set_ylabel("median |location error| (m)", color=PALETTE["lightning"])
    ax2.grid(False)
    ax.invert_xaxis()
    return _save(fig, out, "13_end_to_end_vs_snr.png")
